package awsmodels

import (
	_ "embed"
	"encoding/json"
	"sync"
)

// glue/model.json is generated by scripts/gen-glue-model.py from the AWS CLI's
// bundled botocore model. It keeps only what the emulator needs: each
// operation's input/output shape, and every reachable shape's type, members,
// required members, enum values and min/max bounds.
//
//go:embed glue/model.json
var glueModelJSON []byte

// Shape is one botocore shape.
type Shape struct {
	Type     string            `json:"t"`
	Members  map[string]string `json:"m,omitempty"`
	Required []string          `json:"r,omitempty"`
	Member   string            `json:"mem,omitempty"`
	Key      string            `json:"k,omitempty"`
	Value    string            `json:"v,omitempty"`
	Enum     []string          `json:"e,omitempty"`
	Min      *float64          `json:"min,omitempty"`
	Max      *float64          `json:"max,omitempty"`
	Document bool              `json:"doc,omitempty"`
}

// ModelOperation names an operation's input and output shapes ("" if none).
type ModelOperation struct {
	Input  string `json:"in"`
	Output string `json:"out"`
}

// ServiceModel is a trimmed botocore service model.
type ServiceModel struct {
	Version    string                    `json:"version"`
	Operations map[string]ModelOperation `json:"operations"`
	Shapes     map[string]*Shape         `json:"shapes"`
}

var (
	glueModelOnce sync.Once
	glueModel     *ServiceModel
)

// GlueModel returns the shared, read-only Glue model.
func GlueModel() *ServiceModel {
	glueModelOnce.Do(func() {
		var m ServiceModel
		if err := json.Unmarshal(glueModelJSON, &m); err != nil {
			panic("awsmodels: invalid glue model: " + err.Error())
		}
		glueModel = &m
	})
	return glueModel
}
